import java.util.*;
public class ConvexHull {
    static long cross(long[] O, long[] A, long[] B) {
        return (A[0]-O[0])*(B[1]-O[1]) - (A[1]-O[1])*(B[0]-O[0]);
    }
    public static long[][] convexHull(long[][] points) {
        int n = points.length;
        if (n < 2) return points;
        Arrays.sort(points, (a,b) -> a[0]!=b[0] ? Long.compare(a[0],b[0]) : Long.compare(a[1],b[1]));
        long[][] hull = new long[2*n][2];
        int k = 0;
        for (int i=0;i<n;i++) { while(k>=2&&cross(hull[k-2],hull[k-1],points[i])<=0) k--; hull[k++]=points[i]; }
        for (int i=n-2,t=k+1;i>=0;i--) { while(k>=t&&cross(hull[k-2],hull[k-1],points[i])<=0) k--; hull[k++]=points[i]; }
        return Arrays.copyOf(hull, k-1);
    }
}

